editorial:
Let dp[c] be the best value with at most capacity c. For each weight w, scan capacities from W down to w, so dp[c−w] still refers to earlier items. Update with that state plus the new value. Time O(nW), space O(W). Use 64 bits for values.
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n,w; cin>>n>>w;
    vector<long long>dp(w+1);
    while(n--) {
        int weight; long long value; cin>>weight>>value;
        for(int c=w;c>=weight;--c) dp[c]=max(dp[c],dp[c-weight]+value);
    }
    cout<<dp[w]<<'\n';
}
~~~
